; pinball.s - VDC pinball engine (Tier 2, reused by Tier 3)
; Table: 40x25 cells at VDC columns 20-59, custom charset at $2000.
; Art pass: two glyph banks. Bank 0 ($2000): ROM font 0-63, table art,
; flipper poses, ball slots $F0-$F7. Bank 1 ($3000, attribute bit 7):
; our bold font 0-63 and the panel / deep-wall art. Physics uses its own
; collision map (tbl_codes, pglyph), so the art never changes the physics.
; Ball: software "glyph sprite" composited into slot glyphs each frame.
; Flippers: 3 pre-drawn poses each (generated by tools/mktable.py).
; No VDC block copy/fill anywhere.
;
; Physics units: x subunit = 1/32 VDC pixel, y subunit = 1/64 scanline
; (1 scanline = 2 square units, so x and y units are the same physical size).
;   column = hi(bx), lx = lo(bx) >> 5
;   row = hi(by) >> 1, ly = ((hi(by) & 1) << 2) | (lo(by) >> 6)
; Velocities are signed bytes in subunits per substep, 2 substeps per frame.

.include "hw/c128.inc"
.include "hw/scr.inc"
.include "lib/macros.inc"
.ifdef TABLE2
.include "table2_data.s"        ; table v2: faithful layout (tools/mktable2.py)
.else
.include "table_data.s"
.endif

; BOT builds only: split-timing checkpoints (CIA1 timer A snapshots) so the
; per-part maxima can be read from VICE (prof_lo/hi: flippers, physics,
; ball, tail). Compiles to nothing in the shipped build.
.ifdef BOT
.macro PROF n
        lda CIA1_TAHI
        sta pt_hi+n
        lda CIA1_TALO
        sta pt_lo+n
.endmacro
.else
.macro PROF n
.endmacro
.endif

.export pb_setup, pb_launch, pb_frame, pb_draw_panels, pb_flippers_rest
.export pb_dim, pb_undim, pb_reset_lights, pb_logo_tint
.exportzp pb_state, pb_score, pb_energ, pb_fruit, pb_bonus, pb_nudges, pb_tgts
.export chr_ram, pb_add_score, pb_sfx, pb_abort, pb_show_score, pb_show_all
.export pb_sfx_tick

.importzp pr_row, pr_col, pr_vcol, pr_color, pr_vattr, pr_mask
.importzp num, tmp, frame, joy2, port1
.import scr_at, scr_vat, set_color, print, printi, putc, fmt_dec, vdc_font
.import vdc_setaddr, vdc_put, vdc_fill, vdc_fillsetup, vdc_wreg, vdc_rreg
.import row40lo, row40hi, row80lo, row80hi

TBLCOL  = 20            ; VDC column of table column 0
SLOTA   = $F0           ; ball slot glyphs F0-F3 (set A), F4-F7 (set B)
VMAX    = 88            ; velocity cap (subunits per substep)
GRAV    = 1
DRAIN_Y = 173*64        ; ball centre below this scanline = drained

C_EMPTY = 0
C_FULL  = 1
C_SHAPE = 2
C_BUMP  = 3
C_SLING = 4
C_TARG  = 5
C_LANE  = 6
C_SPIN  = 7

; pb_state values
PB_READY   = 0          ; GET READY countdown, no ball yet
PB_PLAY    = 1
PB_DRAINED = 2

.segment "ZEROPAGE"
pb_state:   .res 1
pb_score:   .res 3
pb_energ:   .res 1
pb_fruit:   .res 1
pb_bonus:   .res 1
pb_nudges:  .res 1
pb_tgts:    .res 1      ; table v2: PAC-MAN targets lit (0-8)
bx:         .res 2
by:         .res 2
vx:         .res 1
vy:         .res 1
obx:        .res 2
oby:        .res 2
nbx:        .res 2
nby:        .res 2
ma:         .res 1
mb:         .res 1
mlo:        .res 1
mhi:        .res 1
msign:      .res 1
nx:         .res 1
ny:         .res 1
dot:        .res 1
wx:         .res 1
wy:         .res 1
pcol:       .res 1      ; probe cell column / row / local x / local y
prow:       .res 1
plx:        .res 1
ply:        .res 1
pcode:      .res 1
pcls:       .res 1
gp:         .res 2      ; glyph pointer
dp:         .res 2      ; disp pointer
pose:       .res 2      ; flipper poses (0 rest .. 2 up)
opose:      .res 2      ; poses drawn on the VDC
fmove:      .res 2      ; flipper moved up this frame
fdown:      .res 1      ; release counter
dxu:        .res 1
dyu:        .res 1
ft:         .res 1
fd:         .res 1
fi:         .res 1
ready_t:    .res 1
wd_frames:  .res 2
trig_cell:  .res 2
lastcls:    .res 1
rnd:        .res 1
; ball render state
bvis:       .res 1
ox0:        .res 1
oy0:        .res 1
ow:         .res 1
oh:         .res 1
nx0:        .res 1
ny0:        .res 1
nw:         .res 1
nh:         .res 1
bshift:     .res 1
broff:      .res 1
slotset:    .res 1
ux0:        .res 1
ux1:        .res 1
uy0:        .res 1
uy1:        .res 1
rx:         .res 1
ry:         .res 1
gbuf:       .res 8
sfx_t:      .res 1
dirty:      .res 1      ; panel needs redraw
dstep:      .res 1
pdx:        .res 1
pdy:        .res 1
chute:      .res 1
botc:       .res 1
botb:       .res 1
chompf:     .res 1
fdrawn:     .res 1      ; a flipper was redrawn this frame
fold:       .res 1      ; drawn pose being replaced ($FF = none)
fend:       .res 1
gq:         .res 2      ; old-pose block pointer

.segment "BSS"
chr_ram:    .res 2048   ; bank 0 copy: codes 0-63 ROM font, 64-255 generated
disp:       .res 1000   ; what the VDC shows for each table cell (no ball)
lit:        .res 10     ; v1: targets 0-3, lanes 4-7; v2: targets 0-7, lanes 8-9
.ifdef BOT
.export prof
pt_lo:      .res 5
pt_hi:      .res 5
prof:       .res 8      ; words: flippers, physics, ball, tail
prof1 = prof+2
prof2 = prof+4
prof3 = prof+6
.export prof1, prof2, prof3
.endif

.segment "CODE"

; ------------------------------------------------------------------------
; pb_setup: fill chr_ram 64-255, upload charset, table, attributes.
; chr_ram codes 0-63 must already hold the ROM font (caller copies them).
pb_setup:
        lda #$80                ; VDC text in the bold font (bank 1)
        sta vdc_font
        ldx #24                 ; hardware blink at 1/32 frame rate (~2 Hz)
        jsr vdc_rreg
        ora #$20
        jsr vdc_wreg
        ; glyph0 -> chr_ram + 64*8
        lda #<glyph0
        sta gp
        lda #>glyph0
        sta gp+1
        lda #<(chr_ram+512)
        sta dp
        lda #>(chr_ram+512)
        sta dp+1
        ldx #6                  ; 6 pages = 192 glyphs
        ldy #0
:       lda (gp),y
        sta (dp),y
        iny
        bne :-
        inc gp+1
        inc dp+1
        dex
        bne :-
        ; upload 256 glyphs to VDC $2000 (16-byte stride)
        lda #$20
        ldy #0
        jsr vdc_setaddr
        lda #<chr_ram
        sta gp
        lda #>chr_ram
        sta gp+1
        ldx #0                  ; glyph counter
@g:     ldy #0
@r:     lda (gp),y
        bit VDC_ADDR
        bpl *-3
        sta VDC_DATA
        iny
        cpy #8
        bne @r
        lda #0
@p:     bit VDC_ADDR
        bpl @p
        sta VDC_DATA
        iny
        cpy #16
        bne @p
        lda gp
        clc
        adc #8
        sta gp
        bcc :+
        inc gp+1
:       inx
        bne @g
        ; bank 1: 256 glyphs straight from glyph1 (continues at $3000)
        lda #<glyph1
        sta gp
        lda #>glyph1
        sta gp+1
        ldx #0
@g1:    ldy #0
@r1:    lda (gp),y
        bit VDC_ADDR
        bpl *-3
        sta VDC_DATA
        iny
        cpy #8
        bne @r1
        lda #0
@p1:    bit VDC_ADDR
        bpl @p1
        sta VDC_DATA
        iny
        cpy #16
        bne @p1
        lda gp
        clc
        adc #8
        sta gp
        bcc :+
        inc gp+1
:       inx
        bne @g1
        ; charset base $2000 (R28 bits 7-5), keep RAM-type bit
        ; (done by vdc_basic_init in the caller)
        ; copy static table into disp, then draw the whole screen
        jsr pb_reset_disp
        jsr draw_screen
        lda #0
        sta pose
        sta pose+1
        lda #$FF
        sta opose
        sta opose+1
        jsr draw_flippers_all
        lda #0
        sta pb_score
        sta pb_score+1
        sta pb_score+2
        sta bvis
        sta ow
        sta oh
        sta dstep
        lda #$5A
        sta rnd
.ifdef BOT
        ldx #7
        lda #0
:       sta prof,x
        dex
        bpl :-
.endif
        rts

pb_reset_disp:
        ldx #0
:       lda vis_codes,x
        sta disp,x
        lda vis_codes+250,x
        sta disp+250,x
        lda vis_codes+500,x
        sta disp+500,x
        lda vis_codes+750,x
        sta disp+750,x
        inx
        cpx #250
        bne :-
        rts

; draw_screen: all 80x25 cells: left panel (20), table (disp, 40),
; right panel (20); then the attributes the same way.
draw_screen:
        lda #0
        sta ry
@row:   ldx ry
        lda row80lo,x
        sta tmp
        lda row80hi,x
        sta tmp+1
        ldy tmp
        jsr vdc_setaddr
        ldx ry
        lda #<pan_codes
        ldy #>pan_codes
        jsr row_ptr40           ; gp = pan_codes + row*40
        lda #<disp
        ldy #>disp
        jsr row_ptr40dp         ; dp = disp + row*40
        jsr put_row
        ; attributes
        lda tmp+1
        clc
        adc #8
        ldy tmp
        jsr vdc_setaddr
        ldx ry
        lda #<pan_attrs
        ldy #>pan_attrs
        jsr row_ptr40
        lda #<vis_attrs
        ldy #>vis_attrs
        jsr row_ptr40dp
        jsr put_row
        inc ry
        lda ry
        cmp #25
        bne @row
        rts

; put_row: 20 bytes from (gp), 40 from (dp), 20 from (gp)+20
put_row:
        ldy #0
:       lda (gp),y
        jsr vdc_put
        iny
        cpy #20
        bne :-
        ldy #0
:       lda (dp),y
        jsr vdc_put
        iny
        cpy #40
        bne :-
        ldy #20
:       lda (gp),y
        jsr vdc_put
        iny
        cpy #40
        bne :-
        rts

; row_ptr40: gp = A/Y + X*40 ; row_ptr40dp: dp = A/Y + X*40
row_ptr40:
        clc
        adc row40lo,x
        sta gp
        tya
        adc row40hi,x
        sta gp+1
        rts
row_ptr40dp:
        clc
        adc row40lo,x
        sta dp
        tya
        adc row40hi,x
        sta dp+1
        rts

; cell_addr0: tmp = X*80 + TBLCOL  (VDC screen address of table row X)
cell_addr0:
        lda row80lo,x
        clc
        adc #TBLCOL
        sta tmp
        lda row80hi,x
        adc #0
        sta tmp+1
        rts

; pb_draw_panels: the panel labels are part of the art (pan_codes);
; just schedule the dynamic fields.
pb_draw_panels:
        lda #1
        sta dirty
        rts

; draw_dynamic: tally and score (VDC panels), field number dstep (4..1)
draw_dynamic:
        MASK 2
        COLOR COL_WHITE
        lda dstep
        cmp #4
        bne @n4
        lda #2
        ldx #62
        jsr scr_at
        lda pb_score
        sta num
        lda pb_score+1
        sta num+1
        lda pb_score+2
        sta num+2
        lda #8
        jsr fmt_dec
        jmp print
@n4:    cmp #3
        bne @n3
        lda #9
        ldx #16
        jsr scr_at
        lda pb_energ
        jmp pr2
@n3:    cmp #2
        bne @n2
        lda #10
        ldx #15
        jsr scr_at
        lda #$2B                ; '+'
        jsr putc
        lda pb_fruit
        jmp pr2
@n2:    lda #11
        ldx #13
        jsr scr_at
        lda pb_bonus
        sta num
        lda #0
        sta num+1
        sta num+2
        lda #5
        jsr fmt_dec
        jmp print
pr2:    sta num
        lda #0
        sta num+1
        sta num+2
        lda #2
        jsr fmt_dec
        jmp print

; ------------------------------------------------------------------------
; pb_reset_lights: unlight targets and lanes, clear the tally
pb_reset_lights:
.ifdef TABLE2
        ldx #NLIGHTS-1
        lda #0
:       sta lit,x
        dex
        bpl :-
        sta pb_energ
        sta pb_fruit
        sta pb_bonus
        sta pb_tgts
        ldx #NLIGHTS-1
:       lda lit_off,x
        jsr paint_light
        dex
        bpl :-
        lda #1
        sta dirty
        rts

; paint_light (v2): light X (all lit_h cells of it) attribute = A.
; Preserves X. ~330 cycles per cell.
paint_light:
        stx fi
        sta tmp+2
        lda lit_row,x
        sta ry
        lda lit_col,x
        sta rx
        lda lit_h,x
        sta fend
@c:     lda tmp+2
        jsr set_cell_attr
        inc ry
        dec fend
        bne @c
        ldx fi
        rts
.else
        ldx #7
        lda #0
:       sta lit,x
        dex
        bpl :-
        sta pb_energ
        sta pb_fruit
        sta pb_bonus
        ldx #7
@l:     txa
        pha
        lda lit_row,x
        sta ry
        lda lit_col,x
        sta rx
        lda lit_off,x
        jsr set_cell_attr
        pla
        tax
        dex
        bpl @l
        lda #1
        sta dirty
        rts
.endif

; set_cell_attr: table cell (ry, rx) attribute = A
set_cell_attr:
        pha
        ldx ry
        jsr cell_addr0
        lda tmp
        clc
        adc rx
        tay
        lda tmp+1
        adc #8
        jsr vdc_setaddr
        pla
        jmp vdc_put

; pb_launch: A = chute (0 left, 1 right). Starts GET READY.
pb_launch:
        sta chute
        lda #PB_READY
        sta pb_state
        lda #60
        sta ready_t
        lda #0
        sta pb_nudges
        sta wd_frames
        sta wd_frames+1
        sta fmove
        sta fmove+1
        lda #$FF
        sta trig_cell
        MASK 2
        COLOR COL_YELLOW
        PRS 13, 5, "GET READY"
        lda #14
        ldx #6
        jsr scr_at
        lda #RGBI_WHITE|$80|$10 ; bank 1, hardware blink
        sta pr_vattr
        lda #<go_big0
        ldx #>go_big0
        jsr print
        lda #15
        ldx #6
        jsr scr_at
        lda #RGBI_WHITE|$80|$10
        sta pr_vattr
        lda #<go_big1
        ldx #>go_big1
        jsr print
        lda #1
        sta dirty
        rts

serve:
        ldx chute
        lda servex_lo,x
        sta bx
        lda servex_hi,x
        sta bx+1
        lda #<(14*64)
        sta by
        lda #>(14*64)
        sta by+1
        jsr random
        and #15
        clc
        adc #20
        ldx chute
        beq :+
        eor #$FF
        clc
        adc #1
:       sta vx
        lda #10
        sta vy
        lda #PB_PLAY
        sta pb_state
        MASK 2
        PRS 13, 5, "         "
        PRS 14, 6, "       "
        PRS 15, 6, "       "
        lda #3
        jsr sfx
        rts

; ------------------------------------------------------------------------
; pb_frame: one 60 Hz frame. Returns A = pb_state.
pb_frame:
        PROF 0
        jsr flipper_input
        jsr draw_flippers
        PROF 1
.ifdef BOT
        lda pt_hi+1
        sta pt_hi+2
        sta pt_hi+3
        lda pt_lo+1
        sta pt_lo+2
        sta pt_lo+3
.endif
        lda pb_state
        cmp #PB_READY
        bne @play
        dec ready_t
        bne @out
        jsr serve
        jmp @out
@play:  cmp #PB_PLAY
        bne @out
        jsr substep
        lda pb_state
        cmp #PB_PLAY
        bne @drn
        jsr substep
        lda pb_state
        cmp #PB_PLAY
        bne @drn
        jsr triggers
        jsr watchdog
        PROF 2
        jsr render_ball
        PROF 3
        jmp @out
@drn:   jsr hide_ball
@out:   lda dirty
        beq :+
        lda #0
        sta dirty
        lda #4
        sta dstep
:       lda dstep
        beq :+
        lda fdrawn              ; frame budget: no text on flipper frames
        bne :+
        jsr draw_dynamic        ; one field per frame
        dec dstep
:       jsr sfx_tick
.ifdef BOT
        PROF 4
        jsr prof_update
.endif
        lda pb_state
        rts

.ifdef BOT
; prof_update: segment i = t[i] - t[i+1] (timer counts down); keep maxima
prof_update:
        ldx #0
@s:     txa
        asl
        tay                     ; Y = word index into prof
        lda pt_lo,x
        sec
        sbc pt_lo+1,x
        sta tmp
        lda pt_hi,x
        sbc pt_hi+1,x
        sta tmp+1
        cmp prof+1,y
        bcc @n
        bne @m
        lda tmp
        cmp prof,y
        bcc @n
@m:     lda tmp+1
        sta prof+1,y
        lda tmp
        sta prof,y
@n:     inx
        cpx #4
        bne @s
        rts
.endif

; flipper_input: left = port1 bit2 or joy2 left; right = port1 bit3 or joy2 right
flipper_input:
        lda #0
        sta fmove
        sta fmove+1
        lda port1
        ora joy2
        sta tmp
.ifdef BOT
        jsr bot
        ora tmp
        sta tmp
.endif
        inc fdown
        ldx #0
@f:     lda tmp
        and flipbit,x
        beq @rel
        lda pose,x
        cmp #2
        beq @nx
        inc pose,x
        lda #1
        sta fmove,x
        cpx #0
        bne @nx
        lda #1
        jsr sfx
        jmp @nx
@rel:   lda fdown
        and #1
        beq @nx
        lda pose,x
        beq @nx
        dec pose,x
@nx:    inx
        cpx #2
        bne @f
        rts

.ifdef BOT
; bot: test-only flipper player. Flips the flipper on the ball's side when
; the ball is low and falling; holds 12 frames, then rests 16 frames.
bot:
        lda botc
        beq @idle
        dec botc
        lda botc
        cmp #16
        bcc @rel
        lda botb
        rts
@rel:   lda #0
        rts
@idle:  lda pb_state
        cmp #PB_PLAY
        bne @rel
        lda by+1
        cmp #(150*64)>>8
        bcc @rel
        lda vy
        bmi @rel
        lda #$04
        ldx bx+1
        cpx #20
        bcc :+
        lda #$08
:       sta botb
        lda #28
        sta botc
        lda botb
        rts
.endif

pb_flippers_rest:
        lda #0
        sta pose
        sta pose+1
        jmp draw_flippers_all

; draw_flippers: redraw flippers whose pose changed. Only the cells that
; differ from the drawn pose are written (per block row, the span from the
; first to the last changed cell): ~1,000 cycles per change instead of
; ~3,300 for the whole 8x5 block. fdrawn = 1 when anything was drawn (the
; panel text then waits a frame).
draw_flippers:
        lda #0
        sta fdrawn
        ldx #0
@f:     lda pose,x
        cmp opose,x
        beq @nx
        stx fi
        jsr draw_block
        ldx fi
        lda pose,x
        sta opose,x
        lda #1
        sta fdrawn
@nx:    inx
        cpx #2
        bne @f
        rts

draw_flippers_all = draw_flippers

; blk_ptr: A = pose, X = flipper -> A/Y = flip_codes + (X*3 + A)*40
blk_ptr:
        sta tmp+2
        txa
        asl
        adc fi                  ; (X == fi here; C = 0 after asl of 0/1)
        adc tmp+2
        tax
        lda mul40lo,x
        clc
        adc #<flip_codes
        pha
        lda mul40hi,x
        adc #>flip_codes
        tay
        pla
        rts

; draw_block: flipper fi from drawn pose opose,fi ($FF = nothing drawn:
; write everything) to pose,fi
draw_block:
        ldx fi
        lda pose,x
        jsr blk_ptr
        sta gp
        sty gp+1
        ldx fi
        lda opose,x
        sta fold
        bmi :+
        jsr blk_ptr
        sta gq
        sty gq+1
:       lda #0
        sta ry                  ; block row
@row:   ; span of changed cells in this row -> rx (first) .. fend (last+1)
        lda fold
        bpl @scan
        lda #0
        sta rx
        lda #FB_W
        sta fend
        bne @draw
@scan:  ldy #0
:       lda (gp),y
        cmp (gq),y
        bne :+
        iny
        cpy #FB_W
        bne :-
        jmp @next               ; row unchanged
:       sty rx
        ldy #FB_W-1
:       lda (gp),y
        cmp (gq),y
        bne :+
        dey
        bne :-
:       iny
        sty fend
@draw:  lda ry
        clc
        adc #FB_ROW
        tax
        jsr cell_addr0
        ldx fi
        lda tmp
        clc
        adc fbcol,x
        sta tmp
        bcc :+
        inc tmp+1
:       lda tmp
        clc
        adc rx
        tay
        lda tmp+1
        adc #0
        jsr vdc_setaddr
        ; disp pointer (row start of the block)
        lda ry
        clc
        adc #FB_ROW
        tax
        lda row40lo,x
        clc
        adc #<disp
        sta dp
        lda row40hi,x
        adc #>disp
        sta dp+1
        ldx fi
        lda dp
        clc
        adc fbcol,x
        sta dp
        bcc :+
        inc dp+1
:       ldy rx
@c:     lda (gp),y
        sta (dp),y
        bit VDC_ADDR
        bpl *-3
        sta VDC_DATA
        iny
        cpy fend
        bne @c
@next:  lda gp
        clc
        adc #FB_W
        sta gp
        bcc :+
        inc gp+1
:       lda gq
        clc
        adc #FB_W
        sta gq
        bcc :+
        inc gq+1
:       inc ry
        lda ry
        cmp #FB_H
        beq :+
        jmp @row
:       rts

; ------------------------------------------------------------------------
; substep: gravity, move with static collision, flippers, drain check
substep:
        lda vy
        clc
        adc #GRAV
        jsr clampv
        sta vy
        ; tentative new position
        lda bx
        sta obx
        lda bx+1
        sta obx+1
        lda by
        sta oby
        lda by+1
        sta oby+1
        lda vx
        ldx #bx
        jsr addv
        lda vy
        ldx #by
        jsr addv
        jsr probe_all
        bcc @moved
        ; hit: normal in nx/ny, class in pcls. Bounce if moving into it.
        jsr bounce_static
        bcc @moved              ; moving away: keep the move
        lda obx                 ; else stay at the old position
        sta bx
        lda obx+1
        sta bx+1
        lda oby
        sta by
        lda oby+1
        sta by+1
@moved: jsr flippers
        ; drain?
        lda by+1
        cmp #>DRAIN_Y
        bcc @x
        bne @d
        lda by
        cmp #<DRAIN_Y
        bcc @x
@d:     lda #PB_DRAINED
        sta pb_state
        lda #4
        jsr sfx
@x:     rts

; addv: add signed A to the 16-bit zp word at X
addv:
        ldy #0
        cmp #$80
        bcc :+
        dey
:       clc
        adc 0,x
        sta 0,x
        tya
        adc 1,x
        sta 1,x
        rts

; clampv: clamp signed A to +-VMAX
clampv:
        bmi @neg
        cmp #VMAX+1
        bcc @ok
        lda #VMAX
@ok:    rts
@neg:   cmp #<(-VMAX)
        bcs @ok
        lda #<(-VMAX)
        rts

; probe_all: test leading probe points at (bx,by). C=1 on hit with
; nx/ny = normal, pcls = class, pcode/prow/pcol = cell.
probe_all:
        ; vertical leading probe: (0, +-2 scanlines)
        lda #0
        sta pdx
        lda vy
        bmi :+
        lda #<(2*64)
        ldx #>(2*64)
        jmp :++
:       lda #<(-2*64)
        ldx #>(-2*64)
:       sta pdy
        stx tmp+3
        jsr probe
        bcc :+
        jsr probe_normal_v
        sec
        rts
:       ; horizontal leading probe: (+-3 px, 0)
        lda vx
        bmi :+
        lda #3*32
        jmp :++
:       lda #<(-3*32)
:       sta pdx
        lda #0
        sta pdy
        sta tmp+3
        jsr probe
        bcc :+
        jsr probe_normal_h
        sec
        rts
:       ; diagonal probe: (+-2 px, +-1 scanline)
        lda vx
        bmi :+
        lda #2*32
        jmp :++
:       lda #<(-2*32)
:       sta pdx
        lda vy
        bmi :+
        lda #64
        ldx #0
        jmp :++
:       lda #<(-64)
        ldx #$FF
:       sta pdy
        stx tmp+3
        jsr probe
        bcc :+
        jsr probe_normal_d
        sec
:       rts

; for full cells the normal opposes the probe direction
probe_normal_v:
        lda pcls
        jsr is_boxy
        bne @x
        lda #0
        sta nx
        lda vy
        bmi :+
        lda #<(-127)
        sta ny
        rts
:       lda #127
        sta ny
@x:     rts
probe_normal_h:
        lda pcls
        jsr is_boxy
        bne @x
        lda #0
        sta ny
        lda vx
        bmi :+
        lda #<(-127)
        sta nx
        rts
:       lda #127
        sta nx
@x:     rts
probe_normal_d:
        lda pcls
        jsr is_boxy
        bne @x
        lda vx
        bmi :+
        lda #<(-90)
        jmp :++
:       lda #90
:       sta nx
        lda vy
        bmi :+
        lda #<(-90)
        jmp :++
:       lda #90
:       sta ny
@x:     rts
; is_boxy: Z=1 if class uses probe-direction normals (full, target)
is_boxy:
        cmp #C_FULL
        beq :+
        cmp #C_TARG
:       rts

; probe: point (bx + pdx, by + pdy:tmp+3) -> C=1 if solid there
probe:
        lda pdx
        ldy #0
        cmp #$80
        bcc :+
        dey
:       clc
        adc bx
        sta nbx
        tya
        adc bx+1
        sta nbx+1
        lda pdy
        clc
        adc by
        sta nby
        lda tmp+3
        adc by+1
        sta nby+1
        ; cell
        lda nbx+1
        cmp #40
        bcs @se
        sta pcol
        lda nby+1
        lsr
        cmp #25
        bcs @se
        sta prow
        tax
        bne @inside             ; row 0 is the top wall
@se:    lda #C_FULL
        sta pcls
        sec
        rts
@inside:
        lda row40lo,x
        clc
        adc pcol
        sta dp
        lda row40hi,x
        adc #0
        sta dp+1
        lda dp
        clc
        adc #<tbl_codes
        sta gp
        lda dp+1
        adc #>tbl_codes
        sta gp+1
        ldy #0
        lda (gp),y
        sta pcode
        tax
        lda gclass,x
        sta pcls
        beq @no                 ; empty
        cmp #C_LANE
        bcs @no                 ; triggers are not solid
        cmp #C_FULL
        beq @yes
        cmp #C_TARG
        beq @yes
        ; shape test against the glyph bitmap
        lda nbx
        lsr
        lsr
        lsr
        lsr
        lsr
        sta plx
        lda nby+1
        and #1
        asl
        asl
        sta ply
        lda nby
        rol
        rol
        rol
        and #3
        ora ply
        sta ply
        ; gp = pglyph + (code-64)*8  (collision bitmap, not the art)
        lda pcode
        sta gp
        lda #0
        sta gp+1
        asl gp
        rol gp+1
        asl gp
        rol gp+1
        asl gp
        rol gp+1
        lda gp
        clc
        adc #<(pglyph-512)
        sta gp
        lda gp+1
        adc #>(pglyph-512)
        sta gp+1
        ldy ply
        lda (gp),y
        ldx plx
        and bitmask,x
        beq @no
        ldx pcode
        lda gnx,x
        sta nx
        lda gny,x
        sta ny
@yes:   sec
        rts
@no:    clc
        rts

; bounce_static: C=1 if the ball was moving into the surface (bounced)
bounce_static:
        jsr calc_dot
        bmi :+
        clc
        rts
:       jsr calc_w              ; wx, wy = dot*n
        lda pcls
        cmp #C_BUMP
        beq @bump
        cmp #C_SLING
        beq @sling
        ; walls, targets: e = 1/2 -> v -= w + w/2
        jsr sub_w
        jsr sub_whalf
        lda pcls
        cmp #C_TARG
        bne @done
        jsr hit_target
        jmp @done
@bump:  jsr sub_w               ; e = 1 -> v -= 2w, plus kick
        jsr sub_w
        lda #44
        jsr kick
        lda #<100
        ldx #>100
        jsr add_score
        lda #2
        jsr sfx
        jmp @done
@sling: jsr sub_w
        jsr sub_whalf
        lda #36
        jsr kick
        lda #10
        ldx #0
        jsr add_score
        lda #2
        jsr sfx
@done:  lda vx
        jsr clampv
        sta vx
        lda vy
        jsr clampv
        sta vy
        sec
        rts

; calc_dot: dot = (vx*nx + vy*ny) >> 7, N flag from dot
calc_dot:
        lda vx
        ldx nx
        jsr smul
        lda mlo
        sta tmp
        lda mhi
        sta tmp+1
        lda vy
        ldx ny
        jsr smul
        lda mlo
        clc
        adc tmp
        sta mlo
        lda mhi
        adc tmp+1
        sta mhi
        jsr shr7
        sta dot
        rts

; calc_w: wx = (dot*nx)>>7, wy = (dot*ny)>>7
calc_w:
        lda dot
        ldx nx
        jsr smul
        jsr shr7
        sta wx
        lda dot
        ldx ny
        jsr smul
        jsr shr7
        sta wy
        rts

sub_w:  lda vx
        sec
        sbc wx
        jsr satv
        sta vx
        lda vy
        sec
        sbc wy
        jsr satv
        sta vy
        rts
sub_whalf:
        lda wx
        cmp #$80
        ror
        sta tmp
        lda vx
        sec
        sbc tmp
        jsr satv
        sta vx
        lda wy
        cmp #$80
        ror
        sta tmp
        lda vy
        sec
        sbc tmp
        jsr satv
        sta vy
        rts
sub_wquarter:
        lda wx
        cmp #$80
        ror
        cmp #$80
        ror
        sta tmp
        lda vx
        sec
        sbc tmp
        jsr satv
        sta vx
        lda wy
        cmp #$80
        ror
        cmp #$80
        ror
        sta tmp
        lda vy
        sec
        sbc tmp
        jsr satv
        sta vy
        rts

; satv: after an 8-bit signed add/sub with V flag, saturate; then clamp
satv:
        bvc :+
        bmi @pos                ; overflowed negative-looking -> was positive
        lda #<(-VMAX)
        rts
@pos:   lda #VMAX
        rts
:       jmp clampv

; kick: v += (A * n) >> 7
kick:
        sta tmp+2
        ldx nx
        jsr smul
        jsr shr7
        clc
        adc vx
        jsr satv
        sta vx
        lda tmp+2
        ldx ny
        jsr smul
        jsr shr7
        clc
        adc vy
        jsr satv
        sta vy
        rts

; smul: signed A * signed X -> mlo/mhi
smul:
        sta ma
        stx mb
        eor mb
        sta msign
        lda ma
        bpl :+
        eor #$FF
        clc
        adc #1
        sta ma
:       lda mb
        bpl :+
        eor #$FF
        clc
        adc #1
        sta mb
:       lda ma
        sta mlo
        lda #0
        ldx #8
        lsr mlo
@l:     bcc :+
        clc
        adc mb
:       ror
        ror mlo
        dex
        bne @l
        sta mhi
        lda msign
        bpl @x
        lda mlo
        eor #$FF
        clc
        adc #1
        sta mlo
        lda mhi
        eor #$FF
        adc #0
        sta mhi
@x:     rts

; shr7: A = (mhi:mlo) >> 7 as a signed byte (saturated)
shr7:
        lda mhi
        bmi @neg
        cmp #$40
        bcs @maxp
        lda mlo
        asl
        lda mhi
        rol
        rts
@maxp:  lda #127
        rts
@neg:   cmp #$C0
        bcc @maxn
        lda mlo
        asl
        lda mhi
        rol
        rts
@maxn:  lda #$80
        rts

; ------------------------------------------------------------------------
; flippers: analytic collision of the ball with both flippers
flippers:
        ldx #0
@f:     stx fi
        jsr flip_one
        ldx fi
        inx
        cpx #2
        bne @f
        rts

flip_one:
        jmp @go1
@n0:    rts
@go1:
        ; dxu = (bx >> 5) - pivot_x   (signed, must fit a byte)
        lda bx+1
        sta tmp+1
        lda bx
        ldy #5
:       lsr tmp+1
        ror
        dey
        bne :-
        sec
        ldx fi
        sbc pivx_lo,x
        sta tmp
        lda tmp+1
        sbc pivx_hi,x
        ; must be in range -12..+60 (left) / -60..+12 (right)
        beq @xpos
        cmp #$FF
        bne @n0
        lda tmp
        cmp #<(-60)
        bcc @n0
        jmp @xok
@xpos:  lda tmp
        cmp #61
        bcs @n0
@xok:   lda tmp
        sta dxu
        ; dyu = (by >> 5) - PIV_SL*2  (units = half scanlines)
        lda by+1
        sta tmp+1
        lda by
        ldy #5
:       lsr tmp+1
        ror
        dey
        bne :-
        sec
        sbc #<(PIV_SL*2)
        sta tmp
        lda tmp+1
        sbc #>(PIV_SL*2)
        beq @ypos
        cmp #$FF
        bne @n0
        lda tmp
        cmp #<(-40)
        bcc @n0
        jmp @yok
@ypos:  lda tmp
        cmp #40
        bcs @n0
@yok:   lda tmp
        sta dyu
        ; pose index
        ldx fi
        lda pose,x
        sta tmp+2
        txa
        asl
        adc fi
        adc tmp+2
        tax                     ; X = fi*3 + pose
        stx tmp+2
        ; t = (dxu*dx + dyu*dy) >> 7
        lda dxu
        ldy fl_dx,x
        jsr smul_y
        lda mlo
        sta wx
        lda mhi
        sta wy
        ldx tmp+2
        lda dyu
        ldy fl_dy,x
        jsr smul_y
        lda mlo
        clc
        adc wx
        sta mlo
        lda mhi
        adc wy
        sta mhi
        jsr shr7
        sta ft
        ; t range -4 .. FLEN+3
        bmi @tneg
        cmp #FLEN+4
        bcc @tok
        rts
@tneg:  cmp #<(-4)
        bcs @tok
        rts
@tok:   ; d = (dxu*nx + dyu*ny) >> 7
        ldx tmp+2
        lda fl_nx,x
        sta nx
        lda fl_ny,x
        sta ny
        lda dxu
        ldx nx
        jsr smul
        lda mlo
        sta wx
        lda mhi
        sta wy
        lda dyu
        ldx ny
        jsr smul
        lda mlo
        clc
        adc wx
        sta mlo
        lda mhi
        adc wy
        sta mhi
        jsr shr7
        sta fd
        ; contact band: -6 (or -24 if the flipper moved up) .. 8
        bmi @dneg
        cmp #9
        bcs @no
        jmp @hit
@dneg:  ldx fi
        ldy fmove,x
        beq :+
        cmp #<(-24)
        bcc @no
        jmp @hit
:       cmp #<(-6)
        bcc @no
@hit:   jsr flip_hit
@no:    rts

smul_y: tax                     ; A * Y (signed) -> mlo/mhi
        tya
        stx tmp+3
        ldx tmp+3
        jmp smul

; flip_hit: push the ball out to d = 9 along n, reflect, and kick if moving
flip_hit:
        lda #9
        sec
        sbc fd                  ; push distance (units)
        ldx nx
        jsr smul
        jsr shr7                ; units in x
        jsr units_x
        lda #9
        sec
        sbc fd
        ldx ny
        jsr smul
        jsr shr7                ; units in y
        jsr units_y
        jsr calc_dot
        bpl :+
        jsr calc_w
        jsr sub_w
        jsr sub_wquarter
:       ldx fi
        lda fmove,x
        beq @x
        ; moving flipper: kick = 34 + t (tip is stronger)
        lda #0
        sta wd_frames
        sta wd_frames+1
        lda ft
        bpl :+
        lda #0
:       clc
        adc #34
        jsr kick
        lda #5
        ldx #0
        jsr add_score
@x:     rts

; units_x: bx += A (signed units) * 32 ; units_y: by += A * 32
units_x:
        ldx #bx
        jmp units_add
units_y:
        ldx #by
units_add:
        sta tmp
        ldy #0
        cmp #$80
        bcc :+
        dey
:       sty tmp+1
        ldy #5
:       asl tmp
        rol tmp+1
        dey
        bne :-
        lda 0,x
        clc
        adc tmp
        sta 0,x
        lda 1,x
        adc tmp+1
        sta 1,x
        rts

; ------------------------------------------------------------------------
; triggers: lanes and spinner under the ball centre
triggers:
        lda bx+1
        sta pcol
        lda by+1
        lsr
        sta prow
        cmp trig_cell+1
        bne :+
        lda pcol
        cmp trig_cell
        beq @x
:       lda pcol
        sta trig_cell
        lda prow
        sta trig_cell+1
        tax
        lda row40lo,x
        clc
        adc pcol
        sta gp
        lda row40hi,x
        adc #>tbl_codes
        sta gp+1
        lda gp
        clc
        adc #<tbl_codes
        sta gp
        bcc :+
        inc gp+1
:       ldy #0
        lda (gp),y
        tax
        lda gclass,x
        cmp #C_LANE
        beq @lane
        cmp #C_SPIN
        beq @spin
@x:     rts
@spin:  lda #50
        ldx #0
        jsr add_score
        lda #1
        jsr sfx
        lda #0
        sta wd_frames
        rts
@lane:
.ifdef TABLE2
        lda #0                  ; v2: FRUITS (left) = light 8, TUNNEL = 9
        sta wd_frames
        ldx #8
        lda pcol
        cmp #20
        bcc :+
        inx
:       jmp light_x
.endif
        ; which lane? search lit_row/lit_col 4..7
        ldx #4
@s:     lda lit_row,x
        cmp prow
        bne @n
        lda lit_col,x
        cmp pcol
        beq @fnd
@n:     inx
        cpx #8
        bne @s
        rts
@fnd:   lda #0
        sta wd_frames
        jmp light_x             ; X = lane index

.ifdef TABLE2
; hit_target (v2): probe cell prow/pcol is one of the 8 PAC-MAN targets
; (each lit_h = 3 cells tall)
hit_target:
        lda #0
        sta wd_frames
        ldx #0
@s:     lda lit_col,x
        cmp pcol
        bne @n
        lda prow
        sec
        sbc lit_row,x
        cmp #3
        bcc light_x
@n:     inx
        cpx #8
        bne @s
        rts

; light_x (v2): X = 0-7 target (0-3 PAC, 4-7 MAN of columns 1-4),
; 8 = FRUITS lane, 9 = TUNNEL lane. Completing a column (PAC + MAN of the
; same number) or a word (all four PAC or all four MAN) earns an energizer
; for the maze. All 8 lit: they reset for another round.
light_x:
        lda lit,x
        beq @new
        lda #<100               ; already lit: 100 and a bonus count
        ldx #>100
        jsr add_score
        inc pb_bonus
        lda #1
        sta dirty
        rts
@new:   lda #1
        sta lit,x
        lda lit_on,x
        jsr paint_light
        cpx #8
        bcc @tgt
        bne @tun
        inc pb_fruit            ; FRUITS lane: better fruit in the maze
        lda #<500
        ldx #>500
        jsr add_score
        lda #6
        jsr sfx
        jmp @d
@tun:   lda #<1000              ; TUNNEL lane
        ldx #>1000
        jsr add_score
        inc pb_bonus
        lda #6
        jsr sfx
        jmp @d
@tgt:   inc pb_tgts
        stx fi
        lda #<200
        ldx #>200
        jsr add_score
        lda #3
        jsr sfx
        ldx fi
        txa                     ; column complete? (partner = X eor 4)
        eor #4
        tay
        lda lit,y
        beq :+
        jsr @energ
:       lda fi                  ; word complete? (lit[base..base+3])
        and #4
        tay
        lda lit,y
        and lit+1,y
        and lit+2,y
        and lit+3,y
        beq :+
        jsr @energ
:       lda pb_tgts
        cmp #8
        bne @d
        ldx #7                  ; all eight: reset them
        lda #0
        sta pb_tgts
:       lda #0
        sta lit,x
        lda lit_off,x
        jsr paint_light
        dex
        bpl :-
@d:     lda #1
        sta dirty
        rts
@energ: inc pb_energ
        lda #<500
        ldx #>500
        jmp add_score

.else
; hit_target: probe cell prow/pcol is a target
hit_target:
        lda #0
        sta wd_frames
        ldx #0
@s:     lda lit_row,x
        cmp prow
        bne @n
        lda lit_col,x
        cmp pcol
        beq light_x
@n:     inx
        cpx #4
        bne @s
        rts

; light_x: light target (X=0-3) or lane (X=4-7)
light_x:
@go:    lda lit,x
        bne @again
        lda #1
        sta lit,x
        txa
        pha
        lda lit_row,x
        sta ry
        lda lit_col,x
        sta rx
        lda lit_on,x
        jsr set_cell_attr
        pla
        tax
        cpx #4
        bcs @lanefirst
        inc pb_energ
        lda #<500
        ldx #>500
        jsr add_score
        lda #3
        jsr sfx
        jmp @d
@lanefirst:
        inc pb_fruit
        lda #<200
        ldx #>200
        jsr add_score
        lda #6
        jsr sfx
        jmp @d
@again: lda #<100
        ldx #>100
        jsr add_score
        inc pb_bonus
@d:     lda #1
        sta dirty
        ; all 4 targets lit -> relight cycle for more energizers
        lda lit
        and lit+1
        and lit+2
        and lit+3
        beq @x
        lda #0
        sta lit
        sta lit+1
        sta lit+2
        sta lit+3
        ldx #3
@u:     txa
        pha
        lda lit_row,x
        sta ry
        lda lit_col,x
        sta rx
        lda lit_off,x
        jsr set_cell_attr
        pla
        tax
        dex
        bpl @u
@x:     rts

.endif

; pb_show_all: redraw all VDC tally/score fields now
pb_show_all:
        lda #4
        sta dstep
:       jsr draw_dynamic
        dec dstep
        bne :-
        rts

; pb_show_score: redraw the VDC score field now
pb_show_score:
        lda #4
        sta dstep
        jsr draw_dynamic
        lda #0
        sta dstep
        rts

pb_abort:
        jsr hide_ball
        lda #PB_DRAINED
        sta pb_state
        rts

; add_score: score += A/X (16-bit)
pb_add_score:
add_score:
        clc
        adc pb_score
        sta pb_score
        txa
        adc pb_score+1
        sta pb_score+1
        bcc :+
        inc pb_score+2
:       lda #1
        sta dirty
        rts

; watchdog: nudge a stuck ball after 10 s, force drain after 3 nudges
watchdog:
        inc wd_frames
        bne :+
        inc wd_frames+1
:       lda wd_frames+1
        cmp #>600
        bcc @x
        bne @fire
        lda wd_frames
        cmp #<600
        bcc @x
@fire:  lda #0
        sta wd_frames
        sta wd_frames+1
        lda pb_nudges
        cmp #3
        bcc @nudge
        lda #PB_DRAINED
        sta pb_state
        rts
@nudge: inc pb_nudges
        lda #<(-70)
        sta vy
        jsr random
        and #63
        sec
        sbc #32
        sta vx
@x:     rts

random:
        lda rnd
        asl
        bcc :+
        eor #$1D
:       sta rnd
        eor frame
        rts

; ------------------------------------------------------------------------
; render_ball: composite the ball into slot glyphs and update the cells
render_ball:
        ; left pixel = (bx >> 5) - 3 ; top scanline = (by >> 6) - 2
        lda bx+1
        sta tmp+1
        lda bx
        ldy #5
:       lsr tmp+1
        ror
        dey
        bne :-
        sec
        sbc #3
        sta tmp
        lda tmp+1
        sbc #0
        sta tmp+1
        lda tmp
        and #7
        sta bshift
        lda tmp+1
        lsr
        lda tmp
        ror
        lsr
        lsr
        sta nx0                 ; (tmp+1:tmp) >> 3, tmp+1 is 0 or 1
        lda by+1
        sta tmp+1
        lda by
        ldy #6
:       lsr tmp+1
        ror
        dey
        bne :-
        sec
        sbc #2
        sta tmp
        and #7
        sta broff
        lda tmp
        lsr
        lsr
        lsr
        sta ny0
        lda #1
        sta nw
        sta nh
        lda bshift
        cmp #2                  ; 7-px ball spills into a 2nd cell at shift 2+
        bcc :+
        inc nw
:       lda broff
        cmp #5
        bcc :+
        inc nh
:       ; choose slot set
        lda slotset
        eor #4
        sta slotset
        ; compose each covered cell
        lda #0
        sta ry
@cy:    lda #0
        sta rx
@cx:    jsr compose_cell
        inc rx
        lda rx
        cmp nw
        bne @cx
        inc ry
        lda ry
        cmp nh
        bne @cy
        ; union box of old and new
        lda nx0
        sta ux0
        clc
        adc nw
        sta ux1
        lda ny0
        sta uy0
        clc
        adc nh
        sta uy1
        lda ow
        beq @nou
        lda ox0
        cmp ux0
        bcs :+
        sta ux0
:       lda ox0
        clc
        adc ow
        cmp ux1
        bcc :+
        sta ux1
:       lda oy0
        cmp uy0
        bcs :+
        sta uy0
:       lda oy0
        clc
        adc oh
        cmp uy1
        bcc :+
        sta uy1
:
@nou:   ; write union rows
        lda uy0
        sta ry
@wr:    ldx ry
        jsr cell_addr0
        lda tmp
        clc
        adc ux0
        tay
        lda tmp+1
        adc #0
        jsr vdc_setaddr
        ldx ry
        lda row40lo,x
        clc
        adc #<disp
        sta dp
        lda row40hi,x
        adc #>disp
        sta dp+1
        ldy ux0
@wc:    ; in new box?
        lda ry
        sec
        sbc ny0
        cmp nh
        bcs @plain
        sta tmp+2
        tya
        sec
        sbc nx0
        cmp nw
        bcs @plain
        ; slot = SLOTA + slotset + rowidx*2 + colidx
        sta tmp+3
        lda tmp+2
        asl
        ora tmp+3
        ora slotset
        ora #SLOTA
        jmp @put
@plain: lda (dp),y
@put:   bit VDC_ADDR
        bpl *-3
        sta VDC_DATA
        iny
        cpy ux1
        bne @wc
        inc ry
        lda ry
        cmp uy1
        bne @wr
        lda nx0
        sta ox0
        lda ny0
        sta oy0
        lda nw
        sta ow
        lda nh
        sta oh
        rts

; compose_cell: cell (nx0+rx, ny0+ry) -> slot glyph
compose_cell:
        ; base glyph = chr_ram[disp[cell]*8]
        lda ny0
        clc
        adc ry
        tax
        lda row40lo,x
        clc
        adc #<disp
        sta dp
        lda row40hi,x
        adc #>disp
        sta dp+1
        lda nx0
        clc
        adc rx
        tay
        lda (dp),y
        sta gp
        lda #0
        sta gp+1
        asl gp
        rol gp+1
        asl gp
        rol gp+1
        asl gp
        rol gp+1
        lda gp
        clc
        adc #<chr_ram
        sta gp
        lda gp+1
        adc #>chr_ram
        sta gp+1
        ldy #7
:       lda (gp),y
        sta gbuf,y
        dey
        bpl :-
        ; OR ball rows: ball row k at cell row (broff + k - ry*8)
        ; ball_bits index = bshift*8 + k*2 + rx
        ldx #0                  ; k
@k:     stx tmp+2
        lda ry
        beq :+
        lda #8
:       sta tmp+3
        txa
        clc
        adc broff
        sec
        sbc tmp+3
        cmp #8
        bcs @skip               ; row not in this cell
        tay
        lda bshift
        asl
        asl
        asl
        sta tmp+3
        txa
        asl
        ora rx
        ora tmp+3
        tax
        lda ball_bits,x
        ora gbuf,y
        sta gbuf,y
        ldx tmp+2
@skip:  inx
        cpx #4
        bne @k
        ; slot address = $2000 + slot*16
        lda ry
        asl
        ora rx
        ora slotset
        ora #SLOTA
        sta tmp+3
        lsr
        lsr
        lsr
        lsr
        clc
        adc #$20
        sta tmp+2
        lda tmp+3
        asl
        asl
        asl
        asl
        tay
        lda tmp+2
        jsr vdc_setaddr
        ldy #0
:       lda gbuf,y
        bit VDC_ADDR
        bpl *-3
        sta VDC_DATA
        iny
        cpy #8
        bne :-
        rts

; hide_ball: restore the cells under the ball
hide_ball:
        lda ow
        beq @x
        lda oy0
        sta ry
@r:     ldx ry
        jsr cell_addr0
        lda tmp
        clc
        adc ox0
        tay
        lda tmp+1
        adc #0
        jsr vdc_setaddr
        ldx ry
        lda row40lo,x
        clc
        adc #<disp
        sta dp
        lda row40hi,x
        adc #>disp
        sta dp+1
        lda ox0
        clc
        adc ow
        sta ux1
        ldy ox0
:       lda (dp),y
        jsr vdc_put
        iny
        cpy ux1
        bne :-
        inc ry
        lda ry
        sec
        sbc oy0
        cmp oh
        bne @r
        lda #0
        sta ow
@x:     rts

; ------------------------------------------------------------------------
; pb_logo_tint: recolour the marquee on the left panel (title colour
; cycling). A = RGBI colour for "BABY" (rows 0-1), X = for "PAC-MAN"
; (rows 2-3). Bank 1 glyphs, so bit 7 stays set. ~6,800 cycles.
pb_logo_tint:
        ora #$80
        sta tmp+2
        txa
        ora #$80
        sta tmp+3
        ldx #0
@r:     stx ry
        lda row80lo,x
        tay
        lda row80hi,x
        clc
        adc #8                  ; attributes at $0800
        jsr vdc_setaddr
        lda tmp+2
        cpx #2
        bcc :+
        lda tmp+3
:       ldy #20
:       jsr vdc_put
        dey
        bne :-
        ldx ry
        inx
        cpx #4
        bne @r
        rts

; ------------------------------------------------------------------------
; pb_dim / pb_undim: paused look (rewrite table attributes darker / normal)
pb_dim:
        lda #1
        bne dimset
pb_undim:
        lda #0
dimset: sta tmp+2
        lda #0
        sta ry
@row:   ldx ry
        jsr cell_addr0
        lda tmp+1
        clc
        adc #8
        ldy tmp
        jsr vdc_setaddr
        ldx ry
        lda row40lo,x
        clc
        adc #<vis_attrs
        sta dp
        lda row40hi,x
        adc #>vis_attrs
        sta dp+1
        ldy #0
@c:     lda (dp),y
        ldx tmp+2
        beq @put
        ; dim: light -> dark sibling (drop intensity and blink, keep bank)
        tax
        and #$0E
        bne :+
        txa
        and #$80
        ora #RGBI_DKGREY
        jmp @put
:       txa
        and #$8E
@put:   jsr vdc_put
        iny
        cpy #40
        bne @c
        inc ry
        lda ry
        cmp #25
        bne @row
        rts

; ------------------------------------------------------------------------
; tiny SID effects on voice 1
; sfx: 1 flipper thwack (noise), 2 bumper / ghost ping, 3 launch / target /
; energizer, 4 drain / death, 5 chomp (alternating "wa-ka"), 6 lane blip.
; The gate is dropped first so every effect restarts its envelope.
pb_sfx:
sfx:
        tax
        lda SID+4               ; gate off: retrigger the envelope
        and #$FE
        sta SID+4
        lda sfxlo,x
        sta SID+0
        lda sfxhi,x
        cpx #5
        bne :+
        lda chompf              ; chomp: alternate two pitches
        eor #1
        sta chompf
        lda #$0E
        ldy chompf
        beq :+
        lda #$15
:       sta SID+1
        lda #$00
        sta SID+2
        lda #$08                ; pulse width 50 %
        sta SID+3
        lda #$09
        sta SID+5               ; attack 0, decay 9
        lda #$00
        sta SID+6
        lda sfxwave,x
        sta SID+4
        lda sfxlen,x
        sta sfx_t
        lda #$0F
        sta SID_VOL
        rts
pb_sfx_tick:
sfx_tick:
        lda sfx_t
        beq :+
        dec sfx_t
        bne :+
        lda SID+4
        and #$FE
        sta SID+4
:       rts

.segment "RODATA"
bitmask:    .byte $80,$40,$20,$10,$08,$04,$02,$01
flipbit:    .byte $04,$08
fbcol:      .byte FB_COLL, FB_COLR
pivx_lo:    .byte <PIVL_X, <PIVR_X
pivx_hi:    .byte >PIVL_X, >PIVR_X
.ifdef TABLE2
servex_lo:  .byte <(SERVE_X*32), <(SERVE_X*32)    ; out of the tunnel arch
servex_hi:  .byte >(SERVE_X*32), >(SERVE_X*32)
.else
servex_lo:  .byte <(52*32), <(268*32)
servex_hi:  .byte >(52*32), >(268*32)
.endif
mul40lo:
.repeat 6, I
            .byte <(I*40)
.endrepeat
mul40hi:
.repeat 6, I
            .byte >(I*40)
.endrepeat
; lights: 0-3 energizer targets, 4-7 fruit lanes: lit_row, lit_col,
; lit_on, lit_off come from the generator (table_data.s)
; sfx: 0 unused, 1 flipper/lane, 2 bumper, 3 launch/target, 4 drain
sfxlo:      .byte 0, $00, $00, $00, $00, $00, $00
sfxhi:      .byte 0, $0A, $38, $40, $06, $0E, $22
sfxwave:    .byte 0, $81, $11, $11, $81, $11, $41
sfxlen:     .byte 0, 3, 5, 6, 20, 3, 4
